import {Ledger} from "../common/ledger.mjs";
import {booking} from "../common/request.mjs";

/** Studio admission policy; journal and replay behavior stay in the shared ledger. */
export class StudioLedger extends Ledger {
  reserve(request) {
    // Resolve existing IDs before capacity checks, including cancelled bookings.
    if (this.byId.has(request.id)) return super.reserve(request);

    const cap = this.catalog.studios.get(request.tenant) ?? this.catalog.default;
    const used = this.usage(request.tenant, request.day);
    if (used + request.units > cap) {
      return {status: "full", id: request.id, remaining: Math.max(0, cap - used)};
    }
    this.post(request);
    return {status: "booked", id: request.id, remaining: cap - used - request.units};
  }
}

export function bookStudio(ledger, input, catalog) {
  const request = booking(input);
  return ledger.reserve(request);
}
import {readFileSync, renameSync, writeFileSync} from "node:fs";
import {createInterface} from "node:readline";
import {pathToFileURL} from "node:url";
import {Ledger} from "./common/ledger.mjs";
import {readCatalog} from "./common/limits.mjs";
import {renew} from "./common/renewals.mjs";
import {InputError, booking, day, name} from "./common/request.mjs";
import {bookStudio, StudioLedger} from "./services/studio.mjs";
import {bookArchive} from "./services/archive.mjs";

export function planner(catalog) {
  const ledgers = {studio: new StudioLedger(catalog), archive: new Ledger(catalog)};
  return function dispatch(op) {
    if (!op || !Object.hasOwn(ledgers, op.service)) {
      throw new InputError("service", "must be studio or archive");
    }
    const ledger = ledgers[op.service];
    switch (op.action) {
      case "renew":
        return renew(ledger, op);
      case "book":
        return op.service === "studio"
          ? bookStudio(ledger, op, catalog)
          : bookArchive(ledger, op);
      case "import":
        return ledger.post(booking(op));
      case "cancel":
        return ledger.cancel(name(op.id, "id"));
      case "lookup":
        return ledger.inspect(name(op.id, "id"));
      case "usage":
        return {units: ledger.usage(name(op.tenant, "tenant"), day(op.day))};
      case "summary":
        return ledger.summary();
      default:
        throw new InputError("action", "is unknown");
    }
  };
}

export function apply(dispatch, operation) {
  try {
    return dispatch(operation);
  } catch (error) {
    if (error instanceof InputError) {
      return {status: "invalid", field: error.field};
    }
    throw error;
  }
}

async function main(argv) {
  const [command, ...args] = argv;
  const catalog = readCatalog();
  if (command === "stage" && (args.length === 1 || args.length === 2)) {
    // Keep coordinated staging as the default; allow a service-only release.
    const release = name(args[0], "release");
    const selected = args[1];
    if (selected !== undefined && !["studio", "archive"].includes(selected)) {
      throw new InputError("service", "must be studio or archive");
    }
    const services = selected === undefined ? ["studio", "archive"] : [selected];
    const file = "fixtures/release-queue.json";
    const queue = JSON.parse(readFileSync(file, "utf8"));
    for (const service of services) {
      if (queue.some(row => row.release === release && row.service === service)) continue;
      const allocations = service === "studio" ? Object.fromEntries(catalog.studios) : {};
      queue.push({release, service, default:catalog.default, allocations});
    }
    writeFileSync(file + ".tmp", JSON.stringify(queue, null, 2) + "\n");
    renameSync(file + ".tmp", file);
